msg.payload = {
    Numero: msg.payload.remote,
    DataInicio: new Date(msg.payload.ts - 3 * 60 * 60 * 1000).toISOString().replace('T', ' '),
    DataFim: new Date(msg.payload.stop - 3 * 60 * 60 * 1000).toISOString().replace('T', ' '),
    //"Responsável": phoneInfo.name, // OU phoneInfo.department
    "Responsável": queueInfo, // OU phoneInfo.department
    Ramal: phoneInfo.number,
    Esperou: msg.payload.duration ? converteSegundos(msg.payload.duration) : calcularDiferenca(msg.payload.ts, msg.payload.stop)
};

return msg;

function converteSegundos(segundos) {
    const horas = Math.floor(segundos / 3600);
    const minutos = Math.floor((segundos % 3600) / 60);
    const seg = segundos % 60;

    // Formata a string para exibir zero à esquerda se necessário
    const formatarZero = (valor) => (valor < 10 ? `0${valor}` : valor);

    // Retorna a hora formatada
    return `${formatarZero(horas)}:${formatarZero(minutos)}:${formatarZero(seg)}`;
}

function calcularDiferenca(tempoInicial, tempoFinal) {
    // Calcula a diferença em milissegundos
    let diferenca = tempoFinal - tempoInicial;

    // Calcula horas, minutos e segundos
    let segundos = Math.floor(diferenca / 1000);
    let minutos = Math.floor(segundos / 60);
    let horas = Math.floor(minutos / 60);

    // Formata os valores para exibir no formato "00:00:00"
    segundos = segundos % 60;
    minutos = minutos % 60;
    horas = horas % 24;

    // Adiciona zeros à esquerda para garantir o formato
    horas = horas < 10 ? '0' + horas : horas;
    minutos = minutos < 10 ? '0' + minutos : minutos;
    segundos = segundos < 10 ? '0' + segundos : segundos;

    // Retorna o tempo formatado
    return `${horas}:${minutos}:${segundos}`;
}

