if (msg.headers?.paused == "true" && msg.infos.overdue == false) {
    //problema, devo reportar
    return msg;
}

const items = msg.payload; // Seu array de 902 objetos
const maxConcurrent = 10;  // Quantidade de requisições simultâneas
const blockedUsers = [];
const nonBlockedUsers = [];
let index = 0;

(async () => {
    // Função do "Trabalhador"
    async function worker() {
        while (index < items.length) {
            const item = items[index++]; // Puxa o próximo da fila
            const url = `https://${item.domain}.ozmap.com.br`;

            try {
                // Faz a requisição usando axios
                const response = await axios.get(url, {
                    timeout: 10000, // Timeout de 10 segundos
                    // Força o axios a não jogar erro apenas se o status for exatamente 200
                    validateStatus: function (status) {
                        return status === 200;
                    }
                });

                // O Axios já converte as chaves dos headers para letras minúsculas
                const isPaused = response.headers['paused'] === 'true';

                if (isPaused && item.overdue === false) {
                    blockedUsers.push(item);
                }
                else if (!isPaused && item.overdue === true) {
                    nonBlockedUsers.push(item);
                }

            } catch (error) {
                // Cai aqui caso: 
                // 1. Dê timeout (ECONNABORTED)
                // 2. Erro de rede / servidor fora (ECONNREFUSED, ENOTFOUND)
                // 3. Status Code diferente de 200 (devido ao validateStatus acima)
                // Ignoramos silenciosamente como solicitado.
            }
        }
    }

    // Cria a pool de trabalhadores
    const workers = [];
    for (let i = 0; i < Math.min(maxConcurrent, items.length); i++) {
        workers.push(worker());
    }

    // Aguarda todos os trabalhadores esvaziarem a fila
    await Promise.all(workers);

    // Retorna a lista final
    msg.payload = {
        blockedUsers: blockedUsers,
        nonBlockedUsers: nonBlockedUsers
    };
    node.send(msg);
    node.done();
})();

